import { ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { UserHttpService } from 'src/app/user-http.service';
import { AirlinesService, Airlines } from 'src/app/services/airlines.service';
import { TicketsService, Tickets } from 'src/app/services/tickets.service';
import { Aircrafts } from 'src/app/services/aircrafts.service';
import { Router } from '@angular/router';


@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
  adminRole = false;
  airlineRole = false;
  passengerRole = false;
  addticket = true;
  username: string = '';

  aircrafts: Aircrafts[] = [];
  tickets: Tickets[] = [];
  private editBackup: Tickets | null=null;

  updateData: {
    name: string,
    revenue: number,
    aircrafts: Aircrafts[]
  } = {
    name: '',
    revenue: 0,
    aircrafts: []
  };

  constructor(
    private us: UserHttpService,
    private airlinesService: AirlinesService,
    private ticketsService: TicketsService,
    private router: Router,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.adminRole = this.us.is_admin();
    this.airlineRole = this.us.is_airline();
    this.passengerRole = this.us.is_passenger();
    this.username = this.us.get_username();

    console.log('Admin?', this.adminRole);
    console.log('Airline?', this.airlineRole);
    console.log('Passenger?', this.passengerRole);
    console.log('Username?', this.username);

    if (this.airlineRole) {
      console.log("Compagnia");
      const email = this.us.get_mail();

      this.airlinesService.getAirlineByMail(email).subscribe({
        next: res => {
          console.log(res);
          console.log(res.mustChangePassword);
          if (res.mustChangePassword) {
            console.log("Devo cambiare password" + res.mustChangePassword);
            this.router.navigate(['/change-password']);
            return;
          }

          // Popola dati aggiornamento
          /*this.updateData.name = res.name;
          this.updateData.revenue = res.revenue;
          this.updateData.aircrafts = res.aircrafts;*/

          // Carica aircraft
          this.airlinesService.getAircraftByMail(email).subscribe({
            next: aircrafts => {
              this.aircrafts = aircrafts;
              console.log("Aerei Ricevuti", aircrafts);
            },
            error: err => console.error('Errore nel recupero aerei:', err)
          });

          // Carica tickets
          this.loadAllTickets();
          /*
          this.ticketsService.getTickets().subscribe({
            next: tickets => {
              this.tickets = tickets.map(t => ({_code : t._code, user : this.us.get_mail(), 
                                                flight : t.flight, seat : t.seat, 
                                                price : t.price, numBag : t.numBag, editing: false}));
              console.log('Biglietti ricevuti:', tickets);
            },
            error: err => console.error('Errore nel recupero biglietti:', err)
          });*/
        },
        error: err => console.error('Errore nel recupero compagnia:', err)
      });
    }
  }

  updateAirlineInfo() {
    const email = this.us.get_mail();
    const data = {
      name: this.updateData.name,
      revenue: this.updateData.revenue
    };

    this.airlinesService.updateAirlines(email, data).subscribe({
      next: res => {
        console.log('Airline aggiornata:', res);
        // Aggiorna localmente in caso di cambiamenti
        this.updateData.name = res.name;
        this.updateData.revenue = res.revenue;
      },
      error: err => {
        console.error('Errore aggiornamento airline:', err);
      }
    });
  }

    // ----- Gestione Biglietti -----

  private loadAllTickets() {
    this.ticketsService.getTickets().subscribe({
      next: data => (this.tickets = data),
      error: err => console.error('Errore caricamento biglietti:', err)
    });
  }

  // ─────────────────────────────
  // 1) CREAZIONE NUOVO BIGLIETTO
  // ─────────────────────────────
  aggiungiBiglietto() {
    this.tickets.unshift({
      _code: '',
      user: '',
      flight: '',
      seat: '',
      price: 0,
      numBag: 0,
      editing: true
    } as any);    // casting perché il model non prevede editing
  }

  // ─────────────────────────────
  // 2) APRI FORM DI MODIFICA
  // ─────────────────────────────
  startEdit(ticket: Tickets, idx: number) {
    this.editBackup = { ...ticket };
    this.tickets[idx].editing = true;
  }

  // ─────────────────────────────
  // 3) SALVA (CREAZIONE O AGGIORNAMENTO)
  // ─────────────────────────────
  salvaBiglietto(idx: number) {
    const t = this.tickets[idx];

    if (!t.flight || !t.seat) {
      alert('Inserisci almeno volo e posto.');
      return;
    }

    // Dati che il backend si aspetta
    const payload = {
      flight: t.flight,
      seat:   t.seat,
      price:  t.price,
      numBag: t.numBag
    };

    if (t._code) {
      // modifica
      this.ticketsService.updateTicket(t._code, payload).subscribe({
        next: () => {
          this.tickets[idx].editing = false;
          this.editBackup = null;
          console.log(`Biglietto ${t._code} aggiornato.`);
        },
        error: err => console.error('Errore modifica:', err)
      });
    } else {
      // creazione
      this.ticketsService.addTickets(payload).subscribe({
        next: res => {
          this.tickets[idx] = {
            ...t,
            _code: res.id,
            editing: false
          } as any;
          console.log(`Biglietto creato con ID ${res.id}.`);
        },
        error: err => console.error('Errore creazione:', err)
      });
    }
  }

  // ─────────────────────────────
  // 4) ANNULLA MODIFICA
  // ─────────────────────────────
  cancelEdit(idx: number) {
    if (!this.editBackup) return;
    this.tickets[idx] = this.editBackup;
    this.tickets[idx].editing = false;
    this.editBackup = null;
  }

  // ─────────────────────────────
  // 5) CANCELLA BIGLIETTO
  // ─────────────────────────────
  deleteTickets(t: Tickets) {
    this.ticketsService.deleteTickets(t._code).subscribe({
      next: () => {
        this.tickets = this.tickets.filter(x => x._code !== t._code);
        console.log(`Biglietto ${t._code} cancellato.`);
      },
      error: err => console.error('Errore cancellazione:', err)
    });
  }

  logout() {
    this.us.logout();
    this.router.navigate(['/search']);
  }
}
